import json, os
def transform(g):
    h,w=len(g),len(g[0])
    from collections import deque
    vis=[[False]*w for _ in range(h)]
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==0 and not vis[i][j]: vis[i][j]=True; q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==0 and not vis[i][j]: vis[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and g[a][b]==0 and not vis[a][b]:
                vis[a][b]=True; q.append((a,b))
    return [[8 if g[i][j]==0 and not vis[i][j] else g[i][j] for j in range(w)] for i in range(h)]

